// Application tables (v2). The auth tables (user, session, account, verification,
// sso_provider) are generated by better-auth into auth-schema.ts.
//
// v2 keeps it to people, their managers and skills:
// - a team is a manager and the people who report to them; there are no units
// - a ROLE is a grouping a manager makes inside their own team (team_role): its name is
//   unique in that team only, a person can be in several, and nobody gets one by themselves
// - one skill entity org-wide (categories and skills are global); the TARGET comes from the
//   roles a person is in
// - only leaf skills are rated (a skill with active sub-skills is a heading)
// - self and confirmed levels are two columns, never one overwritten by the other
//   (the confirmed one is called "validated" in the code, "confirmed" on screen)
// - "not assessed" is NULL, never 0
// - gaps, coverage and on-target % are computed, never stored
import {
  pgTable, text, integer, boolean, timestamp, jsonb, primaryKey, uniqueIndex, index,
} from "drizzle-orm/pg-core";
import { user } from "./auth-schema.ts";

export * from "./auth-schema.ts";

const id = () => text("id").primaryKey().$defaultFn(() => crypto.randomUUID());
const created = () => timestamp("created_at", { withTimezone: true }).defaultNow().notNull();

// ---- people -------------------------------------------------------------------------

// A grade is a label on a person (Associate, Senior ...): it no longer changes any target.
export const grade = pgTable("grade", {
  id: id(),
  name: text("name").notNull().unique(),
  rank: integer("rank").notNull().default(0),
});

export const employee = pgTable("employee", {
  id: id(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  /** the designation, e.g. "Senior Engineer" */
  title: text("title").notNull().default(""),
  /** what this person's team is called, when they manage one (default "<name>'s team") */
  teamName: text("team_name").notNull().default(""),
  gradeId: text("grade_id").references(() => grade.id, { onDelete: "set null" }),
  managerId: text("manager_id"),
  userId: text("user_id").references(() => user.id, { onDelete: "set null" }).unique(),
  location: text("location").notNull().default(""),
  active: boolean("active").notNull().default(true),
  // ---- from the user directory (ServiceNow sys_user) when the sync is in use
  /** manual (created here or by CSV) | directory (owned by the sync) */
  source: text("source").notNull().default("manual"),
  /** the directory's record id (sys_id) */
  externalId: text("external_id").unique(),
  /** the directory login name (user_name) */
  userName: text("user_name"),
  /** the value of the configured user-type field, e.g. human / machine */
  userType: text("user_type").notNull().default(""),
  /** every synced field, raw, for the photo URL template and the info panel */
  attributes: jsonb("attributes").$type<Record<string, string>>().notNull().default({}),
  syncedAt: timestamp("synced_at", { withTimezone: true }),
  createdAt: created(),
}, (t) => [index("employee_manager_idx").on(t.managerId), index("employee_user_name_idx").on(t.userName),
  index("employee_grade_idx").on(t.gradeId)]);

// ---- skills and levels ------------------------------------------------------------------

export const skillCategory = pgTable("skill_category", {
  id: id(),
  name: text("name").notNull().unique(),
  description: text("description").notNull().default(""),
  sort: integer("sort").notNull().default(0),
});

export const skill = pgTable("skill", {
  id: id(),
  categoryId: text("category_id").notNull().references(() => skillCategory.id, { onDelete: "restrict" }),
  parentId: text("parent_id"),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
  aliases: text("aliases").array().notNull().default([]),
  // draft | active | retired
  status: text("status").notNull().default("active"),
  sort: integer("sort").notNull().default(0),
  createdAt: created(),
}, (t) => [index("skill_category_idx").on(t.categoryId), index("skill_parent_idx").on(t.parentId)]);

export const proficiencyLevel = pgTable("proficiency_level", {
  level: integer("level").primaryKey(),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
});

// ---- what a team needs ------------------------------------------------------------------------

// What a manager's team needs: "at least N people at level L in skill S". The team is the
// manager and everyone below them.
export const teamNeed = pgTable("team_need", {
  id: id(),
  managerId: text("manager_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  minLevel: integer("min_level").notNull(),
  headcount: integer("headcount").notNull().default(1),
  note: text("note").notNull().default(""),
  /** a need the team's roles imply that the manager took off the list: it stays off */
  dismissed: boolean("dismissed").notNull().default(false),
}, (t) => [uniqueIndex("team_need_uq").on(t.managerId, t.skillId), index("team_need_skill_idx").on(t.skillId)]);

// ---- a team's roles ---------------------------------------------------------------------------
// A role belongs to one team (its manager). The manager makes as many as the team needs, puts
// people in them and says which skills each one asks for.

export const teamRole = pgTable("team_role", {
  id: id(),
  managerId: text("manager_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
  /** its tint, a key of src/lib/role-colors.ts; "" = the next colour its team does not use yet */
  color: text("color").notNull().default(""),
  sort: integer("sort").notNull().default(0),
  createdAt: created(),
}, (t) => [uniqueIndex("team_role_name_uq").on(t.managerId, t.name), index("team_role_manager_idx").on(t.managerId)]);

export const teamRoleMember = pgTable("team_role_member", {
  roleId: text("role_id").notNull().references(() => teamRole.id, { onDelete: "cascade" }),
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
}, (t) => [primaryKey({ columns: [t.roleId, t.employeeId] }), index("team_role_member_employee_idx").on(t.employeeId)]);

export const teamRoleSkill = pgTable("team_role_skill", {
  roleId: text("role_id").notNull().references(() => teamRole.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  target: integer("target").notNull(),
  /** a must-have (true) or a nice-to-have */
  mandatory: boolean("mandatory").notNull().default(true),
}, (t) => [primaryKey({ columns: [t.roleId, t.skillId] }), index("team_role_skill_skill_idx").on(t.skillId)]);

// A skill a manager asks of ONE person, beyond what their roles ask: "Priya also needs
// Kubernetes at 3". It counts like a role's skill (a target, a gap, the grid), belongs to the
// manager's team (a person who moves to another manager leaves it behind) and goes through
// the team's draft like every other change.
export const teamPersonSkill = pgTable("team_person_skill", {
  managerId: text("manager_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  target: integer("target").notNull(),
  mandatory: boolean("mandatory").notNull().default(true),
  /** why, in the manager's words: shown to the person */
  note: text("note").notNull().default(""),
}, (t) => [primaryKey({ columns: [t.managerId, t.employeeId, t.skillId] }), index("team_person_skill_employee_idx").on(t.employeeId), index("team_person_skill_skill_idx").on(t.skillId)]);

// Changes to a team's roles and needs that are not confirmed yet: the whole team setup as it
// would be (src/lib/team-setup.ts), one per team. Nothing counts until it is confirmed.
export const teamDraft = pgTable("team_draft", {
  managerId: text("manager_id").primaryKey().references(() => employee.id, { onDelete: "cascade" }),
  doc: jsonb("doc").notNull(),
  authorId: text("author_id"),
  authorName: text("author_name").notNull().default(""),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
});

// ---- asking for a new skill or category ---------------------------------------------------------
// Skills and categories are the same for everyone, so a new one is asked for and a coordinator
// (or an administrator) approves it, sends it back with a note, or says no with a reason.
export const catalogueRequest = pgTable("catalogue_request", {
  id: id(),
  // skill | category
  kind: text("kind").notNull(),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
  /** for a skill: the category it should go in ... */
  categoryId: text("category_id"),
  /** ... or the name of a category that is asked for too */
  categoryName: text("category_name").notNull().default(""),
  /** for a sub-skill: the skill it goes under */
  parentId: text("parent_id"),
  /** why it is needed, in the asker's words */
  reason: text("reason").notNull().default(""),
  // pending (waits for a coordinator) | returned (back with the asker, to change) | approved | rejected | withdrawn
  status: text("status").notNull().default("pending"),
  requestedById: text("requested_by_id"),
  requestedByEmployeeId: text("requested_by_employee_id"),
  requestedByName: text("requested_by_name").notNull().default(""),
  createdAt: created(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  decidedById: text("decided_by_id"),
  decidedByName: text("decided_by_name").notNull().default(""),
  decidedAt: timestamp("decided_at", { withTimezone: true }),
  /** the coordinator's note: why it came back, why not, or what was changed */
  comment: text("comment").notNull().default(""),
  /** the skill or category that was made from it */
  resultId: text("result_id"),
  /** what happened to it, oldest first */
  history: jsonb("history").$type<{ at: string; by: string; action: string; note: string }[]>().notNull().default([]),
}, (t) => [index("catalogue_request_status_idx").on(t.status), index("catalogue_request_by_idx").on(t.requestedById)]);

// ---- assessment -----------------------------------------------------------------------------

// The CURRENT state of one person's rating of one skill.
export const rating = pgTable("rating", {
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  selfLevel: integer("self_level"),
  selfComment: text("self_comment").notNull().default(""),
  selfAt: timestamp("self_at", { withTimezone: true }),
  /** the level the manager confirmed */
  validatedLevel: integer("validated_level"),
  validatedBy: text("validated_by"),
  validatedAt: timestamp("validated_at", { withTimezone: true }),
  managerComment: text("manager_comment").notNull().default(""),
  /** the person would like to grow in this skill */
  interest: boolean("interest").notNull().default(false),
  // draft (saved, not sent) | submitted (waiting for the manager) | validated (confirmed) | returned (sent back)
  status: text("status").notNull().default("draft"),
}, (t) => [primaryKey({ columns: [t.employeeId, t.skillId] }), index("rating_status_idx").on(t.status), index("rating_skill_idx").on(t.skillId)]);

// Append-only history of every rating change.
export const ratingEvent = pgTable("rating_event", {
  id: id(),
  employeeId: text("employee_id").notNull(),
  skillId: text("skill_id").notNull(),
  // self | submit | validate | return
  kind: text("kind").notNull(),
  level: integer("level"),
  note: text("note").notNull().default(""),
  actorId: text("actor_id"),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [index("rating_event_emp_idx").on(t.employeeId, t.skillId), index("rating_event_at_idx").on(t.at)]);

// ---- running it ------------------------------------------------------------------------------

// One row per directory sync (manual, scheduled or a dry run from the Test button).
export const syncRun = pgTable("sync_run", {
  id: id(),
  trigger: text("trigger").notNull(), // manual | schedule
  status: text("status").notNull().default("running"), // running | ok | failed
  startedAt: timestamp("started_at", { withTimezone: true }).defaultNow().notNull(),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
  fetched: integer("fetched").notNull().default(0),
  created: integer("created").notNull().default(0),
  updated: integer("updated").notNull().default(0),
  deactivated: integer("deactivated").notNull().default(0),
  skipped: integer("skipped").notNull().default(0),
  message: text("message").notNull().default(""),
  actorName: text("actor_name").notNull().default(""),
}, (t) => [index("sync_run_started_idx").on(t.startedAt)]);

export const appSetting = pgTable("app_setting", {
  key: text("key").primaryKey(),
  value: jsonb("value").notNull(),
});

export const auditLog = pgTable("audit_log", {
  id: id(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
  actorId: text("actor_id"),
  actorName: text("actor_name").notNull().default(""),
  action: text("action").notNull(),
  entity: text("entity").notNull(),
  entityId: text("entity_id"),
  detail: jsonb("detail"),
}, (t) => [index("audit_log_at_idx").on(t.at)]);

// Bumped by database triggers whenever data the engine reads changes, so every worker can
// keep its computed picture in memory and rebuild it only on change.
export const dataVersion = pgTable("data_version", {
  id: integer("id").primaryKey(),
  v: integer("v").notNull().default(0),
});

// A job (directory sync, scheduled backup, e-mail) runs in one worker at a time: the worker
// that holds the lease until it expires.
export const jobLease = pgTable("job_lease", {
  name: text("name").primaryKey(),
  holder: text("holder").notNull(),
  until: timestamp("until", { withTimezone: true }).notNull(),
});

// Single sign-on test captures (Settings › Single sign-on), shared by all workers.
export const ssoAttempt = pgTable("sso_attempt", {
  id: id(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
  payload: jsonb("payload").notNull(),
}, (t) => [index("sso_attempt_at_idx").on(t.at)]);

// The person a single sign-on was matched to, until the account is linked on first use.
export const ssoPending = pgTable("sso_pending", {
  email: text("email").primaryKey(),
  employeeId: text("employee_id").notNull(),
  // account fields mapped from the sign-in (Settings › Single sign-on), applied when the account is linked
  profile: jsonb("profile").$type<{ name?: string; email?: string; userName?: string }>(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
});

// ---- e-mail (Settings › E-mail) ------------------------------------------------------------
// Every e-mail the app sends, as an outbox: written when something happens, sent by whichever
// worker holds the outbox lease, then kept as the log. Returns and confirmations wait a moment
// (sendAfter) so several from one sitting go out as one e-mail. dedupeKey keeps a reminder
// from going out twice.
export const emailMessage = pgTable("email_message", {
  id: id(),
  // test | submitted | returned | validated | reminder | nudge | digest
  kind: text("kind").notNull(),
  // the person it is about
  employeeId: text("employee_id"),
  toEmail: text("to_email").notNull(),
  toName: text("to_name").notNull().default(""),
  // what the e-mail shows (names, skills, levels, notes), captured when it was written
  payload: jsonb("payload").notNull().default({}),
  // pending | sent | failed
  status: text("status").notNull().default("pending"),
  subject: text("subject").notNull().default(""),
  error: text("error").notNull().default(""),
  attempts: integer("attempts").notNull().default(0),
  dedupeKey: text("dedupe_key"),
  createdAt: created(),
  sendAfter: timestamp("send_after", { withTimezone: true }).defaultNow().notNull(),
  sentAt: timestamp("sent_at", { withTimezone: true }),
}, (t) => [index("email_message_due_idx").on(t.status, t.sendAfter), index("email_message_created_idx").on(t.createdAt), uniqueIndex("email_message_dedupe_uq").on(t.dedupeKey)]);

// ---- groups from ServiceNow (sys_user_group / sys_user_grmember) ----------------------------
// Imported by the directory sync for the people it brings in; used to decide who may sign in.

export const snGroup = pgTable("sn_group", {
  id: id(),
  // the group's sys_id: stable across syncs, and what access rules refer to
  externalId: text("external_id").notNull().unique(),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
  email: text("email").notNull().default(""),
  managerExternalId: text("manager_external_id"),
  active: boolean("active").notNull().default(true),
  syncedAt: timestamp("synced_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [index("sn_group_name_idx").on(t.name)]);

export const groupMember = pgTable("group_member", {
  groupId: text("group_id").notNull().references(() => snGroup.id, { onDelete: "cascade" }),
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
}, (t) => [primaryKey({ columns: [t.groupId, t.employeeId] }), index("group_member_employee_idx").on(t.employeeId)]);
